//! Temporary encrypted upload buffer; the live vault is not locked while chunks arrive.
use std::{fs,io::{self,Read},path::PathBuf};
use std::os::unix::fs::{OpenOptionsExt,MetadataExt};
use std::os::unix::io::{AsRawFd,FromRawFd};
use std::io::Write;
#[cfg(target_os="macos")] unsafe fn errno_ptr()->*mut libc::c_int{libc::__error()}
#[cfg(target_os="linux")] unsafe fn errno_ptr()->*mut libc::c_int{libc::__errno_location()}
const PREFIX:&str="atlas-encrypted-upload-";
const OWNER_MAGIC:&[u8]=b"atlas-encrypted-spool-v1";
fn cleanup_one(base:&std::path::Path,name:&std::ffi::OsStr,expected:Option<(u64,u64)>)->io::Result<bool>{cleanup_one_inner(base,name,expected,|_,_|{})}
fn cleanup_one_inner(base:&std::path::Path,name:&std::ffi::OsStr,expected:Option<(u64,u64)>,after_move:impl FnOnce(&std::path::Path,&std::ffi::OsStr))->io::Result<bool>{
 use std::os::unix::ffi::{OsStrExt,OsStringExt};
 let bytes=name.as_bytes();if bytes.len()!=PREFIX.len()+32||!bytes.starts_with(PREFIX.as_bytes())||!bytes[PREFIX.len()..].iter().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase()){return Ok(false)}
 let parent=fs::OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC).open(base)?;let n=std::ffi::CString::new(bytes).map_err(io::Error::other)?;
 let raw=unsafe{libc::openat(parent.as_raw_fd(),n.as_ptr(),libc::O_RDONLY|libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if raw<0{return Ok(false)}let dir=unsafe{fs::File::from_raw_fd(raw)};let m=dir.metadata()?;if !m.is_dir()||m.uid()!=unsafe{libc::geteuid()}||m.mode()&0o077!=0||expected.is_some_and(|v|v!=(m.dev(),m.ino())){return Ok(false)}
 let mark=std::ffi::CString::new(".owner").unwrap();let raw=unsafe{libc::openat(dir.as_raw_fd(),mark.as_ptr(),libc::O_RDONLY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if raw<0{return Ok(false)}let mut lock=unsafe{fs::File::from_raw_fd(raw)};let lm=lock.metadata()?;if !lm.is_file()||lm.uid()!=unsafe{libc::geteuid()}||lm.nlink()!=1||lm.mode()&0o077!=0{return Ok(false)}if unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{return Ok(false)}let mut magic=Vec::new();(&mut lock).take(256).read_to_end(&mut magic)?;let Some(identity)=std::str::from_utf8(&magic).ok().and_then(|v|v.strip_prefix("atlas-encrypted-spool-v1:")).and_then(|v|v.split_once(':')).and_then(|(d,i)|Some((d.parse::<u64>().ok()?,i.parse::<u64>().ok()?))) else{return Ok(false)};
 let current=fs::symlink_metadata(base.join(name))?;if !current.is_dir()||current.dev()!=m.dev()||current.ino()!=m.ino(){return Ok(false)}
 let copy=unsafe{libc::dup(dir.as_raw_fd())};if copy<0{return Err(io::Error::last_os_error())}let list=unsafe{libc::fdopendir(copy)};if list.is_null(){unsafe{libc::close(copy)};return Err(io::Error::last_os_error())}let mut data_name=None;let mut known=true;let mut dir_error=0;loop{unsafe{*errno_ptr()=0};let item=unsafe{libc::readdir(list)};if item.is_null(){dir_error=unsafe{*errno_ptr()};break}let value=unsafe{std::ffi::CStr::from_ptr((*item).d_name.as_ptr())}.to_bytes();if [b".".as_slice(),b"..".as_slice(),b".owner".as_slice()].contains(&value){continue}let is_data=value==b"upload.bin"||value.len()==38&&value.starts_with(b".reap-")&&value[6..].iter().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase());if !is_data||data_name.is_some(){known=false;break}data_name=Some(std::ffi::OsString::from_vec(value.to_vec()));}unsafe{libc::closedir(list)};if dir_error!=0{return Err(io::Error::from_raw_os_error(dir_error))}if !known{return Ok(false)}
 if let Some(data_name)=data_name{let source=std::ffi::CString::new(data_name.as_bytes()).map_err(io::Error::other)?;let raw=unsafe{libc::openat(dir.as_raw_fd(),source.as_ptr(),libc::O_RDONLY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if raw<0{return Ok(false)}let pinned=unsafe{fs::File::from_raw_fd(raw)};let fm=pinned.metadata()?;if !fm.is_file()||fm.uid()!=unsafe{libc::geteuid()}||fm.nlink()!=1||(fm.dev(),fm.ino())!=identity{return Ok(false)}
  let quarantine=if data_name.as_bytes()==b"upload.bin"{let q=std::ffi::OsString::from(format!(".reap-{}",uuid::Uuid::new_v4().simple()));let qc=std::ffi::CString::new(q.as_bytes()).map_err(io::Error::other)?;
   #[cfg(target_os="macos")] let moved=unsafe{libc::renameatx_np(dir.as_raw_fd(),source.as_ptr(),dir.as_raw_fd(),qc.as_ptr(),libc::RENAME_EXCL)};
   #[cfg(target_os="linux")] let moved=unsafe{libc::renameat2(dir.as_raw_fd(),source.as_ptr(),dir.as_raw_fd(),qc.as_ptr(),libc::RENAME_NOREPLACE)};
   if moved!=0{return Err(io::Error::last_os_error())}dir.sync_all()?;after_move(&base.join(name),&q);q
  }else{data_name};
  let qc=std::ffi::CString::new(quarantine.as_bytes()).map_err(io::Error::other)?;let mut st=unsafe{std::mem::zeroed::<libc::stat>()};if unsafe{libc::fstatat(dir.as_raw_fd(),qc.as_ptr(),&mut st,libc::AT_SYMLINK_NOFOLLOW)}!=0||st.st_mode&libc::S_IFMT!=libc::S_IFREG||st.st_uid!=unsafe{libc::geteuid()}||st.st_nlink!=1||(st.st_dev as u64,st.st_ino as u64)!=identity{return Ok(false)}
  if unsafe{libc::unlinkat(dir.as_raw_fd(),qc.as_ptr(),0)}!=0{return Err(io::Error::last_os_error())}
 }
 let current=fs::symlink_metadata(base.join(name))?;if current.dev()!=m.dev()||current.ino()!=m.ino(){return Ok(false)}if unsafe{libc::unlinkat(dir.as_raw_fd(),mark.as_ptr(),0)}!=0{return Err(io::Error::last_os_error())}if unsafe{libc::unlinkat(parent.as_raw_fd(),n.as_ptr(),libc::AT_REMOVEDIR)}!=0{return Err(io::Error::last_os_error())}Ok(true)
}
pub fn cleanup_stale(base:&std::path::Path){if let Ok(entries)=fs::read_dir(base){for entry in entries.flatten(){let _=cleanup_one(base,&entry.file_name(),None);}}}
const MAX:u64=10*1024*1024*1024;
use chacha20poly1305::{XChaCha20Poly1305,XNonce,KeyInit,aead::{Aead,Payload}};
use zeroize::Zeroizing;
use std::os::unix::fs::FileExt;
pub struct EncryptedSpool {data:Option<fs::File>,dir:PathBuf,expected:u64,written:u64,next:u64,dev:u64,ino:u64,owner:Option<fs::File>,_dirfd:fs::File,key:Zeroizing<[u8;32]>,prefix:[u8;16],poisoned:bool}
fn nonce(prefix:&[u8;16],n:u64)->[u8;24]{let mut value=[0u8;24];value[..16].copy_from_slice(prefix);value[16..].copy_from_slice(&n.to_be_bytes());value}
impl EncryptedSpool {
 pub fn new(expected:u64)->Result<Self,String>{Self::new_inner(expected,|_|{})}
 fn new_inner(expected:u64,after_lock:impl FnOnce(&std::path::Path))->Result<Self,String>{
  if expected>MAX{return Err("invalid upload size".into())}
  let base=std::env::temp_dir().canonicalize().map_err(|e|e.to_string())?;cleanup_stale(&base);
  let parent=fs::OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&base).map_err(|e|e.to_string())?;
  let name=format!("{}{}",PREFIX,uuid::Uuid::new_v4().simple());let cname=std::ffi::CString::new(name.as_bytes()).map_err(|e|e.to_string())?;
  if unsafe{libc::mkdirat(parent.as_raw_fd(),cname.as_ptr(),0o700)}!=0{return Err(io::Error::last_os_error().to_string())}
  let raw=unsafe{libc::openat(parent.as_raw_fd(),cname.as_ptr(),libc::O_RDONLY|libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if raw<0{return Err(io::Error::last_os_error().to_string())}let dirfd=unsafe{fs::File::from_raw_fd(raw)};let m=dirfd.metadata().map_err(|e|e.to_string())?;if !m.is_dir()||m.uid()!=unsafe{libc::geteuid()}||m.mode()&0o077!=0{return Err("unsafe spool directory".into())}let identity=(m.dev(),m.ino());let dir=base.join(&name);
  let marker=std::ffi::CString::new(".owner").unwrap();let raw=unsafe{libc::openat(dirfd.as_raw_fd(),marker.as_ptr(),libc::O_RDWR|libc::O_CREAT|libc::O_EXCL|libc::O_NOFOLLOW|libc::O_CLOEXEC,0o600)};if raw<0{return Err(io::Error::last_os_error().to_string())}let mut owner=unsafe{fs::File::from_raw_fd(raw)};
  if unsafe{libc::flock(owner.as_raw_fd(),libc::LOCK_EX)}!=0{return Err("spool lock unavailable".into())}after_lock(&dir);owner.write_all(OWNER_MAGIC).map_err(|e|e.to_string())?;owner.sync_all().map_err(|e|e.to_string())?;
  let result=(||->Result<(fs::File,Zeroizing<[u8;32]>,[u8;16]),String>{let mut random=fs::File::open("/dev/urandom").map_err(|e|e.to_string())?;let mut key=Zeroizing::new([0u8;32]);let mut prefix=[0u8;16];random.read_exact(key.as_mut()).map_err(|e|e.to_string())?;random.read_exact(&mut prefix).map_err(|e|e.to_string())?;let filename=std::ffi::CString::new("upload.bin").unwrap();let raw=unsafe{libc::openat(dirfd.as_raw_fd(),filename.as_ptr(),libc::O_RDWR|libc::O_CREAT|libc::O_EXCL|libc::O_NOFOLLOW|libc::O_CLOEXEC,0o600)};if raw<0{return Err(io::Error::last_os_error().to_string())}let file=unsafe{fs::File::from_raw_fd(raw)};let fm=file.metadata().map_err(|e|e.to_string())?;if !fm.is_file()||fm.uid()!=unsafe{libc::geteuid()}||fm.nlink()!=1{return Err("unsafe spool file".into())}owner.set_len(0).map_err(|e|e.to_string())?;use std::io::Seek;owner.rewind().map_err(|e|e.to_string())?;write!(owner,"{}:{}:{}",std::str::from_utf8(OWNER_MAGIC).unwrap(),fm.dev(),fm.ino()).map_err(|e|e.to_string())?;owner.sync_all().map_err(|e|e.to_string())?;Ok((file,key,prefix))})();
  match result{Ok((file,key,prefix))=>Ok(Self{data:Some(file),dir,expected,written:0,next:0,dev:identity.0,ino:identity.1,owner:Some(owner),_dirfd:dirfd,key,prefix,poisoned:false}),Err(e)=>{drop(owner);let _=cleanup_one(&base,std::ffi::OsStr::new(&name),Some(identity));Err(e)}}
 }
 pub fn push(&mut self,bytes:&[u8])->Result<u64,String>{if self.poisoned||bytes.is_empty()||bytes.len()>65536{return Err("invalid chunk".into())}let n=self.written.checked_add(bytes.len() as u64).ok_or("upload too large")?;if n>self.expected{return Err("upload too large".into())}let cipher=XChaCha20Poly1305::new_from_slice(self.key.as_ref()).map_err(|_|"encryption unavailable")?;let nonce=nonce(&self.prefix,self.next);let aad=self.next.to_be_bytes();let encrypted=cipher.encrypt(XNonce::from_slice(&nonce),Payload{msg:bytes,aad:&aad}).map_err(|_|"encryption failed")?;let file=self.data.as_mut().ok_or("closed")?;if let Err(e)=file.write_all(&(encrypted.len() as u32).to_be_bytes()).and_then(|_|file.write_all(&encrypted)){self.poisoned=true;return Err(e.to_string())}self.next+=1;self.written=n;Ok(n)}
 pub fn reader(&self)->Result<SpoolReader,String>{if self.poisoned||self.written!=self.expected{return Err("incomplete upload".into())}let file=self.data.as_ref().ok_or("closed")?.try_clone().map_err(|e|e.to_string())?;Ok(SpoolReader{file,offset:0,key:Zeroizing::new(*self.key),prefix:self.prefix,next:0,count:self.next,current:Zeroizing::new(Vec::new()),position:0})}
}
pub struct SpoolReader{file:fs::File,offset:u64,key:Zeroizing<[u8;32]>,prefix:[u8;16],next:u64,count:u64,current:Zeroizing<Vec<u8>>,position:usize}
impl SpoolReader{fn read_exact_at(&mut self,out:&mut[u8])->io::Result<()>{let mut pos=0;while pos<out.len(){let n=self.file.read_at(&mut out[pos..],self.offset)?;if n==0{return Err(io::Error::new(io::ErrorKind::UnexpectedEof,"incomplete encrypted spool"))}self.offset+=n as u64;pos+=n;}Ok(())}}
impl Read for SpoolReader{fn read(&mut self,out:&mut[u8])->io::Result<usize>{if out.is_empty(){return Ok(0)}if self.position==self.current.len(){if self.next==self.count{return Ok(0)}let mut len=[0u8;4];self.read_exact_at(&mut len)?;let len=u32::from_be_bytes(len) as usize;if !(17..=65552).contains(&len){return Err(io::Error::other("invalid encrypted chunk"))}let mut encrypted=vec![0u8;len];self.read_exact_at(&mut encrypted)?;let cipher=XChaCha20Poly1305::new_from_slice(self.key.as_ref()).map_err(io::Error::other)?;let n=nonce(&self.prefix,self.next);let aad=self.next.to_be_bytes();let plain=cipher.decrypt(XNonce::from_slice(&n),Payload{msg:&encrypted,aad:&aad}).map_err(|_|io::Error::other("invalid encrypted chunk"))?;self.current=Zeroizing::new(plain);self.position=0;self.next+=1;}let n=out.len().min(self.current.len()-self.position);out[..n].copy_from_slice(&self.current[self.position..self.position+n]);self.position+=n;Ok(n)}}
impl Drop for EncryptedSpool{fn drop(&mut self){self.data.take();self.owner.take();if fs::symlink_metadata(&self.dir).ok().is_some_and(|m|m.is_dir()&&!m.file_type().is_symlink()&&m.dev()==self.dev&&m.ino()==self.ino){if let (Some(base),Some(name))=(self.dir.parent(),self.dir.file_name()){let _=cleanup_one(base,name,Some((self.dev,self.ino)));}}}}
#[cfg(test)] mod tests{use super::*;#[test]fn stale_is_removed_but_active_is_retained(){let base=std::env::temp_dir();let active=EncryptedSpool::new(0).unwrap();let path=active.dir.clone();cleanup_stale(&base);assert!(path.exists());let mut stale=EncryptedSpool::new(0).unwrap();let stale_path=stale.dir.clone();stale.data.take();stale.owner.take();std::mem::forget(stale);cleanup_stale(&base);assert!(!stale_path.exists());assert!(path.exists());drop(active);}
#[test]fn crash_child(){let Some(ready)=std::env::var_os("ATLAS_SPOOL_CRASH_READY")else{return};let mut spool=EncryptedSpool::new(21).unwrap();spool.push(b"crash-secret-contents").unwrap();fs::write(ready,spool.dir.to_string_lossy().as_bytes()).unwrap();loop{std::thread::sleep(std::time::Duration::from_secs(1));}}
#[test]fn killed_process_spool_is_reaped(){use std::process::{Command,Stdio};struct ChildGuard(std::process::Child);impl Drop for ChildGuard{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}let root=std::env::temp_dir().join(format!("atlas-spool-test-{}",uuid::Uuid::new_v4().simple()));fs::create_dir(&root).unwrap();let ready=root.join("ready");let mut child=ChildGuard(Command::new(std::env::current_exe().unwrap()).args(["--exact","agent_encrypted_spool::tests::crash_child","--nocapture"]).env("TMPDIR",&root).env("ATLAS_SPOOL_CRASH_READY",&ready).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap());let deadline=std::time::Instant::now()+std::time::Duration::from_secs(10);while !ready.exists()&&std::time::Instant::now()<deadline{std::thread::sleep(std::time::Duration::from_millis(10))}assert!(ready.exists());let spool=PathBuf::from(fs::read_to_string(&ready).unwrap());let disk=fs::read(spool.join("upload.bin")).unwrap();assert!(!disk.windows(21).any(|v|v==b"crash-secret-contents"));child.0.kill().unwrap();child.0.wait().unwrap();cleanup_stale(&root);assert!(!spool.exists());drop(child);fs::remove_dir_all(root).unwrap();}
#[test]fn cleanup_does_not_touch_initializing_spool(){let (ready_tx,ready_rx)=std::sync::mpsc::channel();let (continue_tx,continue_rx)=std::sync::mpsc::channel();let thread=std::thread::spawn(move||EncryptedSpool::new_inner(0,|dir|{ready_tx.send(dir.to_path_buf()).unwrap();continue_rx.recv().unwrap();}).unwrap());let path=ready_rx.recv().unwrap();cleanup_stale(path.parent().unwrap());assert!(path.exists());continue_tx.send(()).unwrap();let spool=thread.join().unwrap();assert!(spool.dir.exists());drop(spool);assert!(!path.exists());}
#[test]fn cleanup_keeps_unknown_entries(){let mut s=EncryptedSpool::new(0).unwrap();let dir=s.dir.clone();s.data.take();s.owner.take();std::mem::forget(s);fs::write(dir.join("unrelated"),b"keep").unwrap();cleanup_stale(dir.parent().unwrap());assert!(dir.join("unrelated").exists());assert!(dir.join(".owner").exists());fs::remove_file(dir.join("unrelated")).unwrap();cleanup_stale(dir.parent().unwrap());assert!(!dir.exists());}
#[test]fn replaced_directory_is_not_removed(){let s=EncryptedSpool::new(0).unwrap();let original=s.dir.with_extension("moved");fs::rename(&s.dir,&original).unwrap();fs::create_dir(&s.dir).unwrap();fs::write(s.dir.join("unrelated"),b"keep").unwrap();let path=s.dir.clone();drop(s);assert!(path.join("unrelated").exists());fs::remove_dir_all(path).unwrap();fs::remove_dir_all(original).unwrap();}
#[test]fn independent_readers_do_not_share_offsets(){let mut s=EncryptedSpool::new(8).unwrap();s.push(b"abcd").unwrap();s.push(b"efgh").unwrap();let mut a=s.reader().unwrap();let mut b=s.reader().unwrap();let mut a1=[0u8;2];a.read_exact(&mut a1).unwrap();let mut all=Vec::new();b.read_to_end(&mut all).unwrap();let mut rest=Vec::new();a.read_to_end(&mut rest).unwrap();assert_eq!(&a1,b"ab");assert_eq!(rest,b"cdefgh");assert_eq!(all,b"abcdefgh");}
#[test]fn cleanup_preserves_swapped_quarantine(){let mut spool=EncryptedSpool::new(4).unwrap();spool.push(b"data").unwrap();let dir=spool.dir.clone();spool.data.take();spool.owner.take();std::mem::forget(spool);let moved=dir.parent().unwrap().join(format!("saved-{}",uuid::Uuid::new_v4()));let result=cleanup_one_inner(dir.parent().unwrap(),dir.file_name().unwrap(),None,|dir,q|{fs::rename(dir.join(q),&moved).unwrap();fs::write(dir.join(q),b"foreign data").unwrap();}).unwrap();assert!(!result);assert!(moved.exists());let entries=fs::read_dir(&dir).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();assert!(entries.iter().any(|p|fs::read(p).ok().as_deref()==Some(b"foreign data")));cleanup_stale(dir.parent().unwrap());assert!(dir.exists());fs::remove_dir_all(&dir).unwrap();fs::remove_file(moved).unwrap();}
#[test]fn cleanup_recovers_interrupted_quarantine(){let mut spool=EncryptedSpool::new(4).unwrap();spool.push(b"data").unwrap();let dir=spool.dir.clone();spool.data.take();spool.owner.take();std::mem::forget(spool);let result=std::panic::catch_unwind(||{let _=cleanup_one_inner(dir.parent().unwrap(),dir.file_name().unwrap(),None,|_,_|panic!("simulated interruption"));});assert!(result.is_err());assert!(dir.exists());cleanup_stale(dir.parent().unwrap());assert!(!dir.exists());}
#[test]fn tampering_is_rejected(){use std::os::unix::fs::FileExt;let mut s=EncryptedSpool::new(4).unwrap();s.push(b"data").unwrap();let mut original=[0u8;1];s.data.as_ref().unwrap().read_exact_at(&mut original,5).unwrap();s.data.as_ref().unwrap().write_all_at(&[original[0]^1],5).unwrap();let mut result=Vec::new();assert!(s.reader().unwrap().read_to_end(&mut result).is_err());}
#[test]fn cleanup_refuses_linked_spool_data(){let base=std::env::temp_dir();let mut s=EncryptedSpool::new(1).unwrap();s.push(b"x").unwrap();let dir=s.dir.clone();s.data.take();s.owner.take();std::mem::forget(s);let other=dir.parent().unwrap().join(format!("other-{}",uuid::Uuid::new_v4()));fs::hard_link(dir.join("upload.bin"),&other).unwrap();cleanup_stale(&base);assert!(dir.join("upload.bin").exists());assert!(other.exists());fs::remove_file(&other).unwrap();cleanup_stale(&base);assert!(!dir.exists());}
#[test]fn encrypted_chunks_round_trip_and_cleanup(){let secret=b"atlas-secret-upload-test-987654321";let path;{let mut s=EncryptedSpool::new(secret.len() as u64).unwrap();path=s.dir.clone();s.push(&secret[..11]).unwrap();assert!(s.reader().is_err());s.push(&secret[11..]).unwrap();let mut out=Vec::new();s.reader().unwrap().read_to_end(&mut out).unwrap();assert_eq!(out,secret);let disk=fs::read(s.dir.join("upload.bin")).unwrap();assert!(!disk.windows(secret.len()).any(|x|x==secret));assert!(s.push(b"x").is_err());}assert!(!path.exists());}}
